let badgeConfig={id:programCatalog[0].id,title:programCatalog[0].title,type:'Certificate',style:'ribbon'};
function badgeGeneratorPage(){return `<div class="oak-wallet"><header class="oak-header"><a href="#credentials"><strong>Scholarion Academy</strong><span>Badge design studio</span></a><a href="#credentials">Back to wallet</a></header><main class="oak-main"><h1>Program badge generator</h1><p>Create reusable artwork for any catalog program. These downloads are unsigned artwork, not issued Open Badges credentials.</p><div class="badge-studio"><form id="badge-config"><label>Program<select name="program">${programCatalog.map(p=>`<option value="${p.id}" ${p.id===badgeConfig.id?'selected':''}>#${p.id} ${esc(p.title)}</option>`).join('')}</select></label><label>Badge title<textarea name="title" maxlength="180" rows="4">${esc(badgeConfig.title)}</textarea></label><label>Credential label<select name="type">${['Certificate','Microcredential','Professional Development','Specialization'].map(t=>`<option ${badgeConfig.type===t?'selected':''}>${t}</option>`).join('')}</select></label><label>Design family<select name="style">${[['ribbon','Certificate shield & ribbon'],['micro','Microcredential shield & ribbon'],['shield','Professional development shield'],['seal','Circular professional development seal']].map(([v,t])=>`<option value="${v}" ${badgeConfig.style===v?'selected':''}>${t}</option>`).join('')}</select></label><p>Reusable vector interpretations of the approved designs; original artwork is preserved in the wallet collection.</p><div class="oak-actions"><button type="button" data-badge="png">Download PNG</button><button type="button" data-badge="svg">Download SVG</button><button type="button" data-badge="all">Export all catalog badges (SVG bundle)</button></div><p id="badge-status" role="status"></p></form><div id="badge-preview" aria-label="Badge preview"></div></div></main></div>`;}
function previewBadge(){try{document.getElementById('badge-preview').innerHTML=BadgeTemplate.svg(badgeConfig);document.getElementById('badge-status').textContent='Preview ready · 1200 × 1200 · Transparent background';}catch(err){document.getElementById('badge-preview').textContent='Enter a title to preview your badge.';document.getElementById('badge-status').textContent=err.message;}}
const beforeBadgeGenerator=render;render=function(){if(location.hash.slice(1)==='badge-generator'){document.getElementById('app').innerHTML=badgeGeneratorPage();document.title='Program badge generator · Scholarion Academy';previewBadge();}else{beforeBadgeGenerator();if(location.hash.slice(1)==='credentials')document.querySelector('.oak-title').insertAdjacentHTML('afterend','<p><a class="button" href="#badge-generator">Create program badges</a></p>');}};
document.addEventListener('input',e=>{if(!e.target.closest('#badge-config'))return;const t=e.target;if(t.name==='program'){const p=programCatalog.find(p=>p.id===Number(t.value));badgeConfig.id=p.id;badgeConfig.title=p.title;document.querySelector('[name="title"]').value=p.title;}else if(['title','type','style'].includes(t.name))badgeConfig[t.name]=t.value;previewBadge();});
document.addEventListener('click',async e=>{const action=e.target.closest('[data-badge]')?.dataset.badge;if(!action)return;try{const svg=BadgeTemplate.svg(badgeConfig),filename='scholarion-program-'+badgeConfig.id+'-'+badgeConfig.style;if(action==='svg')download(filename+'.svg',svg,'image/svg+xml');if(action==='all'){const records=programCatalog.map(p=>({programId:p.id,title:p.title,filename:'scholarion-program-'+p.id+'.svg',svg:BadgeTemplate.svg({...badgeConfig,id:p.id,title:p.title})}));download('scholarion-catalog-badges.json',JSON.stringify({format:'SVG artwork bundle',signed:false,style:badgeConfig.style,records},null,2),'application/json');}if(action==='png'){const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));try{const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('PNG render failed. Download SVG instead.'));img.src=url;});const canvas=document.createElement('canvas');canvas.width=canvas.height=1200;canvas.getContext('2d').drawImage(img,0,0,1200,1200);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('PNG export failed.');const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=filename+'.png';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),10000);}finally{URL.revokeObjectURL(url);}}document.getElementById('badge-status').textContent='Artwork export created. No credential was issued.';}catch(err){document.getElementById('badge-status').textContent=err.message;}});
render();
